//! Known-answer tests against vectors generated by the official Python SDK
//! (see `tests/vectors/PROVENANCE.md`). Outputs must match byte for byte.

#![cfg(feature = "server")]

use std::time::Duration;

use cybersource::auth::{SigningInput, authenticate, digest};
use cybersource::clock::FixedClock;
use cybersource::config::{Config, Credentials, Environment};
use cybersource::entropy::FixedEntropy;
use http::Method;
use serde::Deserialize;

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/");

#[derive(Deserialize)]
struct DigestVector {
    body: String,
    expected: String,
}

#[derive(Deserialize)]
struct JwtVector {
    name: String,
    epoch: u64,
    jti: String,
    method: String,
    host: String,
    target: String,
    body: Option<String>,
    merchant_id: String,
    portfolio_id: Option<String>,
    key_id: Option<String>,
    secret: Option<String>,
    key_pem: Option<String>,
    cert_pem: Option<String>,
    expected_token: String,
}

fn load<T: for<'de> Deserialize<'de>>(file: &str) -> Vec<T> {
    let path = format!("{}/tests/vectors/{file}", env!("CARGO_MANIFEST_DIR"));
    let vectors: Vec<T> = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert!(!vectors.is_empty(), "{file} has no vectors");
    vectors
}

fn config(merchant_id: &str, portfolio_id: Option<&str>, credentials: Credentials) -> Config {
    Config::builder()
        .environment(Environment::Test)
        .merchant_id(merchant_id)
        .maybe_portfolio_id(portfolio_id)
        .credentials(credentials)
        .build()
        .unwrap()
}

/// Entropy that makes `uuid_v4` produce `jti`. Only supports UUIDs whose
/// version/variant nibbles are already set, which the vectors use.
fn entropy_for(jti: &str) -> FixedEntropy {
    let hex: String = jti.chars().filter(|c| *c != '-').collect();
    let bytes = (0..16)
        .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
        .collect();
    FixedEntropy(bytes)
}

#[test]
fn digests_match_sdk() {
    for v in load::<DigestVector>("digest.json") {
        assert_eq!(
            digest::sha256_b64(v.body.as_bytes()),
            v.expected,
            "body {:?}",
            v.body
        );
    }
}

#[test]
fn jwt_tokens_match_sdk_byte_for_byte() {
    for v in load::<JwtVector>("jwt.json") {
        let credentials = match (&v.key_id, &v.secret, &v.key_pem, &v.cert_pem) {
            (Some(key_id), Some(secret), None, None) => {
                Credentials::jwt_shared_secret(key_id, secret).unwrap()
            }
            (None, None, Some(key), Some(cert)) => Credentials::jwt_rsa_pem(
                &std::fs::read_to_string(format!("{FIXTURES}{key}")).unwrap(),
                &std::fs::read_to_string(format!("{FIXTURES}{cert}")).unwrap(),
            )
            .unwrap(),
            _ => panic!("{}: unexpected credential fields", v.name),
        };
        let config = config(&v.merchant_id, v.portfolio_id.as_deref(), credentials);
        assert_eq!(config.environment().host(), v.host);
        let method: Method = v.method.parse().unwrap();
        let input = SigningInput {
            method: &method,
            target: &v.target,
            body: v.body.as_deref().unwrap_or("").as_bytes(),
        };

        let headers = authenticate(
            &config,
            &input,
            &FixedClock(Duration::from_secs(v.epoch)),
            &entropy_for(&v.jti),
        )
        .unwrap();

        assert_eq!(
            headers["authorization"].to_str().unwrap(),
            format!("Bearer {}", v.expected_token),
            "{}",
            v.name
        );
        assert_eq!(
            headers["v-c-merchant-id"],
            v.merchant_id.as_str(),
            "{}",
            v.name
        );
        assert!(
            headers.get("date").is_none(),
            "{}: JWT sends no date",
            v.name
        );
    }
}

#[cfg(feature = "http-signature")]
mod http_signature {
    use super::*;

    #[derive(Deserialize)]
    struct HttpSignatureVector {
        name: String,
        epoch: u64,
        method: String,
        host: String,
        target: String,
        body: Option<String>,
        merchant_id: String,
        portfolio_id: Option<String>,
        key_id: String,
        secret: String,
        expected_date: String,
        expected_signature: String,
    }

    #[test]
    fn signatures_match_sdk_byte_for_byte() {
        for v in load::<HttpSignatureVector>("http_signature.json") {
            let credentials = Credentials::http_signature(&v.key_id, &v.secret).unwrap();
            let config = config(&v.merchant_id, v.portfolio_id.as_deref(), credentials);
            assert_eq!(config.environment().host(), v.host);
            let method: Method = v.method.parse().unwrap();
            let body = v.body.as_deref().unwrap_or("");
            let input = SigningInput {
                method: &method,
                target: &v.target,
                body: body.as_bytes(),
            };

            let headers = authenticate(
                &config,
                &input,
                &FixedClock(Duration::from_secs(v.epoch)),
                &FixedEntropy(vec![0]),
            )
            .unwrap();

            assert_eq!(headers["date"], v.expected_date.as_str(), "{}", v.name);
            assert_eq!(
                headers["signature"],
                v.expected_signature.as_str(),
                "{}",
                v.name
            );
            // With a meta key the portfolio is signed, but the header still
            // names the transacting merchant.
            assert_eq!(
                headers["v-c-merchant-id"],
                v.merchant_id.as_str(),
                "{}",
                v.name
            );
            match v.body {
                Some(body) => assert_eq!(
                    headers["digest"].to_str().unwrap(),
                    digest::http_digest_header(body.as_bytes()),
                    "{}",
                    v.name
                ),
                None => assert!(headers.get("digest").is_none(), "{}", v.name),
            }
        }
    }
}

/// The SDK produced the RS256 vectors from `testmerchant.p12`; loading the
/// same P12 through our parser must give byte-identical tokens.
#[cfg(feature = "p12")]
#[test]
fn rs256_tokens_match_sdk_via_p12() {
    let p12 = std::fs::read(format!("{FIXTURES}testmerchant.p12")).unwrap();
    let vectors: Vec<JwtVector> = load::<JwtVector>("jwt.json")
        .into_iter()
        .filter(|v| v.key_pem.is_some())
        .collect();
    assert!(!vectors.is_empty());
    for v in vectors {
        let credentials = Credentials::jwt_p12(&p12, "testmerchant", "testmerchant").unwrap();
        let config = config(&v.merchant_id, v.portfolio_id.as_deref(), credentials);
        let method: Method = v.method.parse().unwrap();
        let input = SigningInput {
            method: &method,
            target: &v.target,
            body: v.body.as_deref().unwrap_or("").as_bytes(),
        };
        let headers = authenticate(
            &config,
            &input,
            &FixedClock(Duration::from_secs(v.epoch)),
            &entropy_for(&v.jti),
        )
        .unwrap();
        assert_eq!(
            headers["authorization"].to_str().unwrap(),
            format!("Bearer {}", v.expected_token),
            "{}",
            v.name
        );
    }
}
